        try {
            // Login first
            loginBeforeProfileTest();

            // Navigate to profile
            profilePage.navigateToProfile();

            // Try to change to weak password
            profilePage.changePassword("Abc12345", "123", "123");
            ReportManager.logInfo("Attempted to change to weak password");

            // Verify error message
            Assert.assertTrue(profilePage.isErrorMessageDisplayed(), "Error message should be displayed for weak password");
            ReportManager.logPass("Weak password properly rejected");

        } catch (Exception e) {
            ReportManager.logFail("Test failed: " + e.getMessage());
            takeScreenshot("UP-PC-03_Failed");
            throw e;
        }
    }

    // Helper method to login before profile tests
    private void loginBeforeProfileTest() {
        // Navigate to login and perform login
        driver.get("https://www.tncstore.vn/");

        // Use authentication page to login
        AuthenticationPage authPage = new AuthenticationPage(driver);
        authPage.performLogin("john@test.com", "Abc12345");

        // Wait for login to complete
        try {
            Thread.sleep(2000);
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        }

        // Verify login success
        Assert.assertTrue(profilePage.isUserLoggedIn(), "User should be logged in before profile tests");
    }
}

package pages;

import config.TNCStoreLocators;
import config.TNCStoreConfig;
import org.openqa.selenium.WebDriver;
import org.openqa.selenium.WebElement;
import org.openqa.selenium.support.FindBy;
import org.openqa.selenium.support.PageFactory;
import org.openqa.selenium.support.ui.WebDriverWait;
import org.openqa.selenium.support.ui.ExpectedConditions;
import java.time.Duration;

public class AuthenticationPage {
    private WebDriver driver;
    private WebDriverWait wait;

    public AuthenticationPage(WebDriver driver) {
        this.driver = driver;
        this.wait = new WebDriverWait(driver, Duration.ofSeconds(TNCStoreConfig.ELEMENT_WAIT));
        PageFactory.initElements(driver, this);
    }

    // Navigation elements using centralized locators
    @FindBy(xpath = TNCStoreLocators.ACCOUNT_BUTTON)
    private WebElement accountButton;

    @FindBy(css = TNCStoreLocators.LOGIN_POPUP)
    private WebElement loginPopup;

    @FindBy(xpath = TNCStoreLocators.CREATE_ACCOUNT_LINK)
    private WebElement createAccountLink;

    // Login elements
    @FindBy(css = TNCStoreLocators.LOGIN_EMAIL_FIELD)
    private WebElement loginEmailField;

    @FindBy(css = TNCStoreLocators.LOGIN_PASSWORD_FIELD)
    private WebElement loginPasswordField;

    @FindBy(xpath = TNCStoreLocators.LOGIN_BUTTON)
    private WebElement loginButton;

    // Register elements
    @FindBy(css = TNCStoreLocators.REGISTER_NAME_FIELD)
    private WebElement registerNameField;

    @FindBy(css = TNCStoreLocators.REGISTER_EMAIL_FIELD)
    private WebElement registerEmailField;

    @FindBy(css = TNCStoreLocators.REGISTER_PASSWORD_FIELD)
    private WebElement registerPasswordField;

    @FindBy(xpath = TNCStoreLocators.REGISTER_BUTTON)
    private WebElement registerButton;

    // Error message elements
    @FindBy(xpath = TNCStoreLocators.ERROR_MESSAGE_GENERAL)
    private WebElement errorMessage;

    @FindBy(xpath = TNCStoreLocators.EMAIL_EXISTS_ERROR)
    private WebElement emailExistsError;

    @FindBy(xpath = TNCStoreLocators.INVALID_EMAIL_ERROR)
    private WebElement invalidEmailError;

    @FindBy(xpath = TNCStoreLocators.REQUIRED_FIELD_ERROR)
    private WebElement requiredFieldError;

    @FindBy(xpath = TNCStoreLocators.LOGOUT_LINK)
    private WebElement logoutLink;

    // Navigation methods
    public void openLoginPopup() {
        wait.until(ExpectedConditions.elementToBeClickable(accountButton));
        accountButton.click();
        wait.until(ExpectedConditions.visibilityOf(loginPopup));
    }

    public void goToRegisterForm() {
        openLoginPopup();
        wait.until(ExpectedConditions.elementToBeClickable(createAccountLink));
        createAccountLink.click();
        wait.until(ExpectedConditions.visibilityOf(registerNameField));
    }

    public void goToLoginForm() {
        openLoginPopup();
        wait.until(ExpectedConditions.visibilityOf(loginEmailField));
    }

    // Registration methods
    public void enterRegisterName(String name) {
        wait.until(ExpectedConditions.visibilityOf(registerNameField));
        registerNameField.clear();
        registerNameField.sendKeys(name);
    }

    public void enterRegisterEmail(String email) {
        wait.until(ExpectedConditions.visibilityOf(registerEmailField));
        registerEmailField.clear();
        registerEmailField.sendKeys(email);
    }

    public void enterRegisterPassword(String password) {
        wait.until(ExpectedConditions.visibilityOf(registerPasswordField));
        registerPasswordField.clear();
        registerPasswordField.sendKeys(password);
    }

    public void clickRegisterButton() {
        wait.until(ExpectedConditions.elementToBeClickable(registerButton));
        registerButton.click();
    }

    // Login methods
    public void enterLoginEmail(String email) {
        wait.until(ExpectedConditions.visibilityOf(loginEmailField));
        loginEmailField.clear();
        loginEmailField.sendKeys(email);
    }

    public void enterLoginPassword(String password) {
        wait.until(ExpectedConditions.visibilityOf(loginPasswordField));
        loginPasswordField.clear();
        loginPasswordField.sendKeys(password);
    }

    public void clickLoginButton() {
        wait.until(ExpectedConditions.elementToBeClickable(loginButton));
        loginButton.click();
    }

    // Validation methods
    public boolean isErrorMessageDisplayed() {
        try {
            return errorMessage.isDisplayed();
        } catch (Exception e) {
            return false;
        }
    }

    public String getErrorMessage() {
        try {
            wait.until(ExpectedConditions.visibilityOf(errorMessage));
            return errorMessage.getText();
        } catch (Exception e) {
            return "";
        }
    }

    public boolean isEmailExistsErrorDisplayed() {
        try {
            return emailExistsError.isDisplayed();
        } catch (Exception e) {
            return false;
        }
    }

    public boolean isInvalidEmailErrorDisplayed() {
        try {
            return invalidEmailError.isDisplayed();
        } catch (Exception e) {
            return false;
        }
    }

    public boolean isRequiredFieldErrorDisplayed() {
        try {
            return requiredFieldError.isDisplayed();
        } catch (Exception e) {
            return false;
        }
    }

    public boolean isLoginSuccessful() {
        try {
            Thread.sleep(2000);
            return !isLoginPopupDisplayed() &&
                   (driver.getCurrentUrl().contains("account") ||
                    driver.getCurrentUrl().contains("profile") ||
                    driver.getPageSource().contains("Đăng xuất"));
        } catch (Exception e) {
            return false;
        }
    }

    public boolean isLoginPopupDisplayed() {
        try {
            return loginPopup.isDisplayed();
        } catch (Exception e) {
            return false;
        }
    }

    // Complete workflows
    public void performRegistration(String name, String email, String password) {
        goToRegisterForm();
        enterRegisterName(name);
        enterRegisterEmail(email);
        enterRegisterPassword(password);
        clickRegisterButton();
    }

    public void performLogin(String email, String password) {
        goToLoginForm();
        enterLoginEmail(email);
        enterLoginPassword(password);
        clickLoginButton();
    }

    // Compatibility methods for old tests
    public void goToRegisterPage() {
        goToRegisterForm();
    }

    public void goToLoginPage() {
        goToLoginForm();
    }

    public void clickForgotPasswordLink() {
        // Not implemented yet - no forgot password in current flow
    }

    public void performForgotPassword(String email) {
        // Not implemented yet - no forgot password in current flow
    }
}

package pages;

import config.TNCStoreLocators;
import config.TNCStoreConfig;
import org.openqa.selenium.WebDriver;
import org.openqa.selenium.WebElement;
import org.openqa.selenium.support.FindBy;
import org.openqa.selenium.support.PageFactory;
import org.openqa.selenium.support.ui.WebDriverWait;
import org.openqa.selenium.support.ui.ExpectedConditions;
import java.time.Duration;

public class UserProfilePage {
    private WebDriver driver;
    private WebDriverWait wait;

    public UserProfilePage(WebDriver driver) {
        this.driver = driver;
        this.wait = new WebDriverWait(driver, Duration.ofSeconds(TNCStoreConfig.ELEMENT_WAIT));
        PageFactory.initElements(driver, this);
    }

    // Profile navigation elements using centralized locators
    @FindBy(xpath = TNCStoreLocators.PROFILE_LINK)
    private WebElement profileLink;

    @FindBy(xpath = TNCStoreLocators.PROFILE_MENU_LINK)
    private WebElement profileMenuLink;

    // Profile form elements
    @FindBy(css = TNCStoreLocators.PROFILE_NAME_FIELD)
    private WebElement nameField;

    @FindBy(css = TNCStoreLocators.PROFILE_EMAIL_FIELD)
    private WebElement emailField;

    @FindBy(css = TNCStoreLocators.PROFILE_PHONE_FIELD)
    private WebElement phoneField;

    @FindBy(css = TNCStoreLocators.PROFILE_ADDRESS_FIELD)
    private WebElement addressField;

    @FindBy(xpath = TNCStoreLocators.SAVE_PROFILE_BUTTON)
    private WebElement saveProfileButton;

    // Password change elements
    @FindBy(css = TNCStoreLocators.CURRENT_PASSWORD_FIELD)
    private WebElement currentPasswordField;

    @FindBy(css = TNCStoreLocators.NEW_PASSWORD_FIELD)
    private WebElement newPasswordField;

    @FindBy(css = TNCStoreLocators.CONFIRM_PASSWORD_FIELD)
    private WebElement confirmPasswordField;

    @FindBy(xpath = TNCStoreLocators.CHANGE_PASSWORD_BUTTON)
    private WebElement changePasswordButton;

    // Message elements
    @FindBy(xpath = TNCStoreLocators.SUCCESS_MESSAGE)
    private WebElement successMessage;

    @FindBy(xpath = TNCStoreLocators.ERROR_MESSAGE_GENERAL)
    private WebElement errorMessage;

    @FindBy(xpath = TNCStoreLocators.EMAIL_EXISTS_ERROR)
    private WebElement emailExistsError;

    @FindBy(xpath = TNCStoreLocators.REQUIRED_FIELD_ERROR)
    private WebElement requiredFieldError;

    // Login popup for authentication check
    @FindBy(css = TNCStoreLocators.LOGIN_POPUP)
    private WebElement loginPopup;

    // Navigation methods
    public void navigateToProfile() {
        try {
            wait.until(ExpectedConditions.elementToBeClickable(profileLink));
            profileLink.click();
            wait.until(ExpectedConditions.visibilityOf(nameField));
        } catch (Exception e) {
            // If direct navigation fails, try URL
            driver.get(TNCStoreConfig.PROFILE_URL);
        }
    }

    // Profile update methods
    public void enterName(String name) {
        if (!name.isEmpty()) {
            wait.until(ExpectedConditions.visibilityOf(nameField));
            nameField.clear();
            nameField.sendKeys(name);
        }
    }

    public void enterEmail(String email) {
        if (!email.isEmpty()) {
            wait.until(ExpectedConditions.visibilityOf(emailField));
            emailField.clear();
            emailField.sendKeys(email);
        }
    }

    public void enterPhone(String phone) {
        if (!phone.isEmpty()) {
            wait.until(ExpectedConditions.visibilityOf(phoneField));
            phoneField.clear();
            phoneField.sendKeys(phone);
        }
    }

    public void enterAddress(String address) {
        if (!address.isEmpty()) {
            wait.until(ExpectedConditions.visibilityOf(addressField));
            addressField.clear();
            addressField.sendKeys(address);
        }
    }

    public void clickSaveProfile() {
        wait.until(ExpectedConditions.elementToBeClickable(saveProfileButton));
        saveProfileButton.click();
    }

    // Password change methods
    public void enterCurrentPassword(String password) {
        wait.until(ExpectedConditions.visibilityOf(currentPasswordField));
        currentPasswordField.clear();
        currentPasswordField.sendKeys(password);
    }

    public void enterNewPassword(String password) {
        wait.until(ExpectedConditions.visibilityOf(newPasswordField));
        newPasswordField.clear();
        newPasswordField.sendKeys(password);
    }

    public void enterConfirmPassword(String password) {
        wait.until(ExpectedConditions.visibilityOf(confirmPasswordField));
        confirmPasswordField.clear();
        confirmPasswordField.sendKeys(password);
    }

    public void clickChangePassword() {
        wait.until(ExpectedConditions.elementToBeClickable(changePasswordButton));
        changePasswordButton.click();
    }

    // Validation methods
    public boolean isProfilePageLoaded() {
        try {
            return nameField.isDisplayed() && emailField.isDisplayed();
        } catch (Exception e) {
            return driver.getCurrentUrl().contains("profile") ||
                   driver.getCurrentUrl().contains("account");
        }
    }

    public boolean isSuccessMessageDisplayed() {
        try {
            return successMessage.isDisplayed();
        } catch (Exception e) {
            return false;
        }
    }

    public boolean isErrorMessageDisplayed() {
        try {
            return errorMessage.isDisplayed();
        } catch (Exception e) {
            return false;
        }
    }

    public boolean isEmailExistsErrorDisplayed() {
        try {
            return emailExistsError.isDisplayed();
        } catch (Exception e) {
            return false;
        }
    }

    public boolean isRequiredFieldErrorDisplayed() {
        try {
            return requiredFieldError.isDisplayed();
        } catch (Exception e) {
            return false;
        }
    }

    public boolean isLoginPopupDisplayed() {
        try {
            return loginPopup.isDisplayed();
        } catch (Exception e) {
            return false;
        }
    }

    // Check if user is logged in
    public boolean isUserLoggedIn() {
        return driver.getPageSource().contains("Đăng xuất") ||
               driver.getCurrentUrl().contains("account") ||
               !isLoginPopupDisplayed();
    }

    // Complete workflows
    public void updateProfile(String name, String email, String phone, String address) {
        navigateToProfile();
        enterName(name);
        enterEmail(email);
        enterPhone(phone);
        enterAddress(address);
        clickSaveProfile();
    }

    public void changePassword(String currentPassword, String newPassword, String confirmPassword) {
        enterCurrentPassword(currentPassword);
        enterNewPassword(newPassword);
        enterConfirmPassword(confirmPassword);
        clickChangePassword();
    }
}

package tests;

import base.BaseTest;
import pages.AuthenticationPage;
import pages.UserProfilePage;
import org.testng.Assert;
import org.testng.annotations.BeforeMethod;
import org.testng.annotations.Test;
import utils.ReportManager;
import data.AuthenticationTestData;

public class TNCStoreTests extends BaseTest {
    private AuthenticationPage authPage;
    private UserProfilePage profilePage;

    @BeforeMethod
    public void setUpTest() {
        // Call parent setup with default browser
        super.setUp("chrome");
        
        // Initialize page objects after driver is created
        authPage = new AuthenticationPage(driver);
        profilePage = new UserProfilePage(driver);
        ReportManager.setModule("tnc-store");
    }

    // ========== AUTHENTICATION GROUP ==========

    @Test(groups = {"authentication", "smoke", "signup"},
          description = "AUTH-SU-01: Register with valid name, email, and password")
    public void testRegisterWithValidData() {
        test = ReportManager.startTest("AUTH-SU-01: Register with valid data");

        try {
            authPage.goToRegisterPage();
            ReportManager.logInfo("Navigated to register page");

            authPage.performRegistration(
                AuthenticationTestData.VALID_NAME,
                AuthenticationTestData.VALID_EMAIL,
                AuthenticationTestData.VALID_PASSWORD
            );
            ReportManager.logInfo("Filled registration form with valid data");

            Assert.assertTrue(authPage.isLoginSuccessful(), "User should be logged in after successful registration");
            ReportManager.logPass("Registration successful");

        } catch (Exception e) {
            ReportManager.logFail("Test failed: " + e.getMessage());
            takeScreenshot("AUTH-SU-01_Failed");
            throw e;
        }
    }

    @Test(groups = {"authentication", "regression", "signup"},
          description = "AUTH-SU-02: Register with existing email")
    public void testRegisterWithExistingEmail() {
        test = ReportManager.startTest("AUTH-SU-02: Register with existing email");

        try {
            authPage.goToRegisterPage();
            ReportManager.logInfo("Navigated to register page");

            authPage.performRegistration(
                AuthenticationTestData.VALID_NAME,
                AuthenticationTestData.EXISTING_EMAIL,
                AuthenticationTestData.VALID_PASSWORD
            );
            ReportManager.logInfo("Attempted registration with existing email");

            Assert.assertTrue(authPage.isErrorMessageDisplayed(), "Error message should be displayed for existing email");
            ReportManager.logPass("Existing email properly rejected");

        } catch (Exception e) {
            ReportManager.logFail("Test failed: " + e.getMessage());
            takeScreenshot("AUTH-SU-02_Failed");
            throw e;
        }
    }

    @Test(groups = {"authentication", "regression", "signup"},
          description = "AUTH-SU-03: Register with invalid email format")
    public void testRegisterWithInvalidEmail() {
        test = ReportManager.startTest("AUTH-SU-03: Register with invalid email format");

        try {
            authPage.goToRegisterPage();
            ReportManager.logInfo("Navigated to register page");

            authPage.performRegistration(
                AuthenticationTestData.VALID_NAME,
                AuthenticationTestData.INVALID_EMAIL_1,
                AuthenticationTestData.VALID_PASSWORD
